import{_ as a,o as e,c as s,a4 as n}from"./chunks/framework.BRzJ4ijD.js";const u=JSON.parse('{"title":"2. 摊还 vs 最坏: 工程常数与硬实时的张力","description":"","frontmatter":{},"headers":[],"relativePath":"_meta/amortized-vs-worst.md","filePath":"_meta/amortized-vs-worst.md","lastUpdated":1788475713000}'),o={name:"_meta/amortized-vs-worst.md"};function d(r,t,i,l,c,p){return e(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="_2-摊还-vs-最坏-工程常数与硬实时的张力" tabindex="-1">2. 摊还 vs 最坏: 工程常数与硬实时的张力 <a class="header-anchor" href="#_2-摊还-vs-最坏-工程常数与硬实时的张力" aria-label="Permalink to &quot;2. 摊还 vs 最坏: 工程常数与硬实时的张力&quot;">​</a></h1><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>&quot;摊还 O(1)&quot; 并不等于 &quot;每一次都是 O(1)&quot; —— 它只承诺<strong>一个足够长的操作序列总和是 O(n)</strong>, 而序列里的某些单次操作本身代价是 O(n). 在一般算法教科书里这个区别无关痛痒, 但在工程中<strong>摊还分析隐含了&quot;操作序列会连续执行下去&quot;这一前提</strong>. 一旦场景是硬实时 (HFT、AVB/TSN、游戏 tick、音视频 P99), <strong>摊还的最坏情况就会被无限放大成一次事故</strong>.</p><h2 id="思想链" tabindex="-1">思想链 <a class="header-anchor" href="#思想链" aria-label="Permalink to &quot;思想链&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工程问题: 平均 1 cycle 的 push, 为什么 P99 会炸出 500 μs?</span></span>
<span class="line"><span>  └─► 摊还分析把&quot;偶尔一次的 O(n)&quot;平摊进长序列</span></span>
<span class="line"><span>        └─► 前提1: 操作序列长时间运行 (∞ 极限下才成立)</span></span>
<span class="line"><span>        └─► 前提2: 批次之间没有外部 deadline</span></span>
<span class="line"><span>        └─► 前提3: 失败可重试, 尖刺不传染给别的请求</span></span>
<span class="line"><span>  └─► 任一前提被打破 (硬实时 / 有界 deadline / 尖刺传染)</span></span>
<span class="line"><span>        └─► 摊还退化成最坏: malloc + memset + copy 全部落在一个请求上</span></span>
<span class="line"><span>              └─► 工程解法: 固定容量 + 环形复用, 摊还 O(1) 变严格 O(1)</span></span>
<span class="line"><span>                    └─► 硬件早就这么干: DMA descriptor ring / NVMe SQ-CQ</span></span></code></pre></div><h2 id="把摊还误读的代价" tabindex="-1">把摊还误读的代价 <a class="header-anchor" href="#把摊还误读的代价" aria-label="Permalink to &quot;把摊还误读的代价&quot;">​</a></h2><p>考虑一个具体场景:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HFT tick 数据流, 每秒 500 万个 tick. 用 std::vector 缓冲.</span></span>
<span class="line"><span>- 平均每次 push 约 1 cycle;</span></span>
<span class="line"><span>- 第 2^23 次 push 触发扩容: malloc 16MB (syscall), memset 写一遍,</span></span>
<span class="line"><span>  再把旧数据 copy 过去 —— 单次耗时 200~800 μs.</span></span></code></pre></div><p>平均 1 cycle ≈ 0.3 ns, 但 P99 ≈ 500 μs. 只看平均值的监控完全无感, 但 500 μs 的抖动在 HFT 上已经超过一个 tick interval——直接丢一帧. 这一类 bug 工程上叫<strong>摊还 bug</strong>, 排查时只能靠 strace / ftrace 抓到那次隐藏的 syscall; 平均延迟曲线上看起来一切完美.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>只看平均值 (甚至只看 P95) 的监控会系统性掩盖摊还尖刺. 判断服务是否吃了摊还亏, 直接看 max / P99.9 与 GC/alloc 日志的相关性; 性能方法论见 <a href="./../engineering/performance-engineering">性能工程: profiling / 火焰图</a>.</p></div><h2 id="摊还成立的前提" tabindex="-1">摊还成立的前提 <a class="header-anchor" href="#摊还成立的前提" aria-label="Permalink to &quot;摊还成立的前提&quot;">​</a></h2><p>摊还分析假设:</p><ol><li>操作序列长时间运行 (∞);</li><li>批次之间没有 deadline;</li><li>失败回滚不影响别人.</li></ol><p>如果其中任何一条被破坏, <strong>摊还就等于最坏</strong>.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>摊还分析的严格定义与聚合法 / 记账法 / 势能法三种证明工具, 见 <a href="./../dsa/algorithms/complexity/amortized">摊还分析入门</a>; 本章关心的是它作为工程假设什么时候失效.</p></div><h2 id="工程上的-反摊还-模式" tabindex="-1">工程上的&quot;反摊还&quot;模式 <a class="header-anchor" href="#工程上的-反摊还-模式" aria-label="Permalink to &quot;工程上的&quot;反摊还&quot;模式&quot;">​</a></h2><p>工程师在硬实时场景下本能地选<strong>最坏可预测的结构</strong>:</p><table tabindex="0"><thead><tr><th>场景</th><th>通常的摊还结构</th><th>改造为最坏可预测</th></tr></thead><tbody><tr><td>HFT 订单簿 (order book)</td><td><code>std::vector</code></td><td>定容 ring buffer + 对象池</td></tr><tr><td>高频网络收包缓冲</td><td><code>std::vector&lt;Packet&gt;</code></td><td><code>boost::lockfree::queue</code> 或定容 ring</td></tr><tr><td>视频采集缓冲</td><td><code>std::vector&lt;Frame&gt;</code></td><td>SPSC ring + 双/三缓冲</td></tr><tr><td>极低延迟哈希表</td><td><code>std::unordered_map</code></td><td>定容开放寻址 (open addressing) + spinlock</td></tr><tr><td>数据库日志缓冲</td><td><code>std::vector</code></td><td>page 对齐 ring + WAL 顺序化</td></tr></tbody></table><p><strong>核心模式</strong>: 用<strong>固定容量 + 环形复用</strong>替代&quot;动态扩容&quot;, 把扩容成本一次性付清. 摊还 O(1) 就变成了严格 O(1).</p><h2 id="硬件层-dma-ring-是-反摊还-的物化" tabindex="-1">硬件层: DMA ring 是&quot;反摊还&quot;的物化 <a class="header-anchor" href="#硬件层-dma-ring-是-反摊还-的物化" aria-label="Permalink to &quot;硬件层: DMA ring 是&quot;反摊还&quot;的物化&quot;">​</a></h2><p>理解 DMA 的工作方式:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PCIe TLP 一次搬运 128B / 256B;</span></span>
<span class="line"><span>异步 + 中断链路;</span></span>
<span class="line"><span>DMA descriptor 排成 ring queue;</span></span>
<span class="line"><span>内核与网卡各维护 RX ring 与 TX ring, 各含 N 个 descriptor,</span></span>
<span class="line"><span>生产者/消费者沿环形推进.</span></span></code></pre></div><p>这个 ring 的工作模式就是一个 lock-free ring buffer. <strong>网卡和 SSD 控制器都按 ring 设计</strong>: DMA 写 head, 内核读 tail, 两边互不改写对方的指针, 各自只 atomic 推进自己负责的那一个. 这种 lock-free ring 是硬件层对&quot;摊还问题&quot;给出的最彻底答案——运行期永远没有分配和搬移, 所有容量在初始化时一次付清.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>NVMe 把这套 ring 思想直接暴露给了主机软件: 64K 个 Submission Queue / Completion Queue 对, 无锁提交 + 可选 polling. 队列模型细节见 <a href="./../computer-arch/ssd-storage">存储硬件: NAND Flash / SSD FTL</a>; 用户态等价物见 <a href="./../os/net/epoll-iouring">epoll / kqueue / io_uring 对比</a>.</p></div><h2 id="fpga-层" tabindex="-1">FPGA 层 <a class="header-anchor" href="#fpga-层" aria-label="Permalink to &quot;FPGA 层&quot;">​</a></h2><p>FPGA 上几乎所有数据通路都是 streaming 的, 没有&quot;扩容&quot;概念. AXI-Stream 的 valid/ready 握手要求双方每一拍都能给出决定; 一旦某一拍没有数据, 流水线就 stall, 整条 pipeline 出现一个 bubble.</p><p>所以 FPGA 设计 = 把全部容量与缓冲预算放在 init / configuration / reconfiguration 阶段完成, <strong>运行时永远不走 O(n) 操作</strong>. 这是 FPGA 项目高可靠的关键: 同步时钟模型一旦部署运行就是<strong>强确定性的</strong>.</p><h2 id="多语言视角下的摊还差异" tabindex="-1">多语言视角下的摊还差异 <a class="header-anchor" href="#多语言视角下的摊还差异" aria-label="Permalink to &quot;多语言视角下的摊还差异&quot;">​</a></h2><table tabindex="0"><thead><tr><th>语言</th><th>默认行为里的摊还尖刺</th><th>显式缓解手段</th></tr></thead><tbody><tr><td>Go</td><td><code>append</code> 扩容 + GC 停顿</td><td><code>make(T, 0, n)</code> 预分配 + GOGC/GOMEMLIMIT 调参</td></tr><tr><td>Java</td><td>HashMap rehash</td><td><code>ConcurrentHashMap</code> 或预估容量构造</td></tr><tr><td>Python</td><td>dict resize 一次性重建</td><td>无法显式预留; 大表改用 list 下标或预估规模建大</td></tr><tr><td>C++</td><td><code>vector::push_back</code> 扩容</td><td><code>reserve</code> + 内存池</td></tr><tr><td>Rust</td><td><code>Vec::push</code> 扩容</td><td><code>Vec::with_capacity</code> + <code>Box</code></td></tr></tbody></table><p>各家都提供了缓解手段, <strong>但缓解永远是显式的</strong>: 默认行为里藏着惊吓. 写高 QPS 服务的工程师必须形成反射: <strong>预分配容量是第一习惯</strong>.</p><h2 id="这一章带走的东西" tabindex="-1">这一章带走的东西 <a class="header-anchor" href="#这一章带走的东西" aria-label="Permalink to &quot;这一章带走的东西&quot;">​</a></h2><ul><li>摊还 = 平均, 不等于最坏. <strong>硬实时场景必须按最坏做预算</strong>;</li><li>网络 ring、DMA ring、FPGA stream 都是硬件层&quot;消灭摊还尖刺&quot;的物化;</li><li>各语言的默认容器都带摊还尖刺, 必须<strong>显式预分配 / 上 lock-free 结构</strong>;</li><li>平均值告诉你吞吐, P99 告诉你抖动——<strong>衡量实时性只能看尾部</strong>.</li></ul><h2 id="一页速查" tabindex="-1">一页速查 <a class="header-anchor" href="#一页速查" aria-label="Permalink to &quot;一页速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>摊还视角</th><th>最坏视角</th></tr></thead><tbody><tr><td>典型结构</td><td>动态数组 / 均摊哈希表</td><td>定容 ring buffer / 定容开放寻址哈希</td></tr><tr><td>承诺强度</td><td>序列总和 O(n)</td><td>每一次操作都有界</td></tr><tr><td>尖刺来源</td><td>扩容 malloc+copy / rehash / GC</td><td>无 (成本在初始化时一次付清)</td></tr><tr><td>适用场景</td><td>吞吐优先的后台与批处理</td><td>HFT / 游戏 tick / 音视频 / 控制 P99</td></tr><tr><td>工程动作</td><td>不用管</td><td><code>reserve</code> / <code>with_capacity</code> / <code>make(T,0,n)</code></td></tr><tr><td>监控指标</td><td>平均延迟</td><td>P99 / P99.9 / max</td></tr></tbody></table><p>下一篇: <a href="./decomposition-strategies">3. 分治 vs 贪心 vs DP: 什么是&quot;最优子问题分解&quot;</a></p>`,35)])])}const g=a(o,[["render",d]]);export{u as __pageData,g as default};
